// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address caller, uint256 amount) public {
        vm.assume(amount > 0);
        vm.assume(caller != address(0));
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool sent,) = address(c).call{value: amount}("");
        require(sent);

        vm.prank(caller);
        c.withdraw();

        assertEq(c.balances(caller), 0);
    }
}
